1	export class QuotaExceededError extends Error {
2	  constructor(code, message) {
3	    super(message);
4	    this.name = 'QuotaExceededError';
5	    this.code = code;
6	  }
7	}
8	
9	// Internal state of every gate, shared with child gates through a WeakMap so
10	// the public gate object keeps its exact shape.
11	const gateState = new WeakMap();
12	
13	// Monotonic counter that never repeats or moves backwards, independent of the
14	// (mocked, possibly frozen) wall clock; gives queued entries a global arrival
15	// order so reparented queues can merge fairly.
16	let enqueueSeq = 0;
17	
18	function assertInteger(value, name) {
19	  if (typeof value !== 'number' || !Number.isInteger(value)) {
20	    throw new TypeError(`${name} must be an integer`);
21	  }
22	}
23	
24	function assertSignal(signal) {
25	  if (
26	    signal !== undefined &&
27	    signal !== null &&
28	    (typeof signal !== 'object' ||
29	      typeof signal.addEventListener !== 'function' ||
30	      typeof signal.removeEventListener !== 'function')
31	  ) {
32	    throw new TypeError('signal must be an AbortSignal');
33	  }
34	}
35	
36	export function createGate({ limit, windowMs, maxWaitMs = 0, parent } = {}) {
37	  assertInteger(limit, 'limit');
38	  assertInteger(windowMs, 'windowMs');
39	  assertInteger(maxWaitMs, 'maxWaitMs');
40	  if (limit <= 0) throw new RangeError('limit must be a positive integer');
41	  if (windowMs <= 0) throw new RangeError('windowMs must be a positive integer');
42	  if (maxWaitMs < 0) throw new RangeError('maxWaitMs must not be negative');
43	
44	  let parentState = null;
45	  if (parent !== undefined && parent !== null) {
46	    parentState = gateState.get(parent);
47	    if (parentState === undefined) {
48	      throw new TypeError('parent must be a gate created by createGate');
49	    }
50	    if (limit > parentState.limit) {
51	      throw new RangeError('limit must not exceed parent limit');
52	    }
53	  }
54	
55	  const state = {
56	    limit,
57	    windowMs,
58	    maxWaitMs,
59	    parent: parentState,
60	    children: new Set(),
61	    isRoot: parentState === null,
62	    // Own-window accounting.
63	    ownGen: 0, // bumped on every own-window flip, invalidates old handles
64	    usedOwn: 0, // own units occupied or lent out in the current own window
65	    inFlight: 0, // units occupied through this gate and not yet cleared
66	    borrowedInFlight: 0, // units this gate's occupations borrowed, still live
67	    lentInFlight: 0, // own units lent to descendants' admitted occupations
68	    poolDraw: 0, // committed pool charge, valid only when drawGen === poolGen
69	    drawGen: -1,
70	    // Cross-gate reservation accounting. A pending acquireAll first reserves
71	    // the member's own current-window slice, then own slices up the direct
72	    // parent chain (each step registering the lend); the root pool covers the
73	    // remainder. Every gathered unit draws pool room until commit or rollback.
74	    //
75	    // A non-root gate's reserved units are pendingOwn + pendingLends: own
76	    // window units promised to pending combos, as member or as ancestor
77	    // lender. The root's reserved units are poolResvUnits: uncommitted units
78	    // drawn from the pool. Across the family every reserved unit counts once.
79	    rolledBack: 0, // failed whole-combo reservation attempts owned here
80	    pendingOwn: 0,
81	    pendingLends: 0,
82	    resvAsMember: new Set(), // entries holding pendingOwn here
83	    resvAsLender: new Set(), // entries holding pendingLends here
84	    lentLinks: new Set(), // admitted occupation links lent from this gate
85	    // Observability.
86	    waiting: 0, // units currently queued through this gate
87	    granted: 0,
88	    refused: 0,
89	    expired: 0,
90	    cancelled: 0,
91	    openHandles: new Set(),
92	    root: null,
93	    timer: null,
94	  };
95	
96	  let root;
97	  if (parentState === null) {
98	    root = state;
99	    // The quota pool shared by the whole hierarchy lives on the root gate.
100	    Object.assign(state, {
101	      poolLimit: limit,
102	      poolGen: 0, // bumped on every root-window flip
103	      poolUsed: 0, // units committed or reserved in the current pool window
104	      poolLinks: new Set(), // admitted pool borrows, reclaimed at the pool flip
105	      poolResv: new Set(), // uncommitted pool reservation links
106	      poolResvUnits: 0, // sum of units behind poolResv
107	      queue: [], // queued requests from every gate, in arrival order
108	      head: 0, // index of the first live entry; entries are never shifted
109	      liveQueued: 0, // entries not yet settled
110	      serveWave: 0, // monotonic count of serves that overtook a blocked combo
111	      minDeadline: Infinity, // earliest live deadline, skips idle sweeps
112	      lastNow: 0, // monotonic clock: never moves backwards
113	      members: new Set(),
114	    });
115	    state.members.add(state);
116	  } else {
117	    root = parentState.root;
118	    root.members.add(state);
119	    parentState.children.add(state);
120	  }
121	  state.root = root;
122	
123	  // Operational helpers read state.root dynamically rather than capturing the
124	  // local `root`: reparent() can move this gate (and its descendants) into
125	  // another family's pool.
126	  function now() {
127	    const r = state.root;
128	    const t = Date.now();
129	    if (t > r.lastNow) r.lastNow = t;
130	    return r.lastNow;
131	  }
132	
133	  function effectiveDraw(node) {
134	    return node.drawGen === node.root.poolGen ? node.poolDraw : 0;
135	  }
136	
137	  function chargeDraw(node, units) {
138	    if (node.drawGen !== node.root.poolGen) {
139	      node.drawGen = node.root.poolGen;
140	      node.poolDraw = 0;
141	    }
142	    node.poolDraw += units;
143	  }
144	
145	  function reservedOn(g) {
146	    return g === g.root ? g.root.poolResvUnits : g.pendingOwn + g.pendingLends;
147	  }
148	
149	  // --- Combo reservations ---------------------------------------------------
150	  //
151	  // seg:  { gate, units, own, ownReleased, links, gen }
152	  // link: { kind:'own'|'pool', lender, units, released, gen }
153	  //
154	  // Gather plans first and applies second, so a plan the pool cannot cover is
155	  // rejected without any mutation and the whole-combo rollback is trivial.
156	  // Sibling members share ancestor chains; the tentative `claimed` map debits
157	  // ancestor headroom cumulatively inside one plan. Every registration is
158	  // intrusive: commit, rollback and window-flip reclaims touch only the gates
159	  // involved, never the queue or the whole family.
160	
161	  function buildSegs(comboGates, unitsOf) {
162	    return comboGates.map((g) => ({
163	      gate: g,
164	      units: unitsOf(g),
165	      own: 0,
166	      ownReleased: false, // member own slice already reclaimed by an own flip
167	      links: [],
168	      gen: -1,
169	    }));
170	  }
171	
172	  function ownHeadroom(g, claimed) {
173	    return Math.max(0, g.limit - g.usedOwn - g.pendingOwn - g.pendingLends - (claimed.get(g) ?? 0));
174	  }
175	
176	  // Pure plan: fills seg.own / seg.links and returns total pool need. A
177	  // member slice larger than that gate's own limit simply borrows the excess
178	  // up the chain — member limits never cap a combo, only the root pool does.
179	  function planGather(segs) {
180	    const r = state.root;
181	    const claimed = new Map();
182	    let poolNeed = 0;
183	    for (const seg of segs) {
184	      const m = seg.gate;
185	      if (m === r) {
186	        seg.links.push({ kind: 'pool', lender: r, units: seg.units, released: false, gen: -1 });
187	        poolNeed += seg.units;
188	        continue;
189	      }
190	      let need = seg.units;
191	      const own = Math.min(need, ownHeadroom(m, claimed));
192	      seg.own = own;
193	      claimed.set(m, (claimed.get(m) ?? 0) + own);
194	      need -= own;
195	      let cur = m.parent;
196	      while (need > 0 && cur !== null && cur !== r) {
197	        const lend = Math.min(need, ownHeadroom(cur, claimed));
198	        if (lend > 0) {
199	          seg.links.push({ kind: 'own', lender: cur, units: lend, released: false, gen: -1 });
200	          claimed.set(cur, (claimed.get(cur) ?? 0) + lend);
201	          need -= lend;
202	        }
203	        cur = cur.parent;
204	      }
205	      if (need > 0) {
206	        seg.links.push({ kind: 'pool', lender: r, units: need, released: false, gen: -1 });
207	        poolNeed += need;
208	      }
209	    }
210	    return poolNeed;
211	  }
212	
213	  // Apply a planned reservation; the caller pre-checked poolNeed against room.
214	  function applyGather(entry, segs) {
215	    const r = entry.owner.root;
216	    const gen = r.poolGen;
217	    for (const seg of segs) {
218	      const m = seg.gate;
219	      seg.gen = gen;
220	      seg.ownReleased = false;
221	      if (m !== r && seg.own > 0) {
222	        m.pendingOwn += seg.own;
223	        m.resvAsMember.add(entry);
224	        r.poolUsed += seg.own;
225	      }
226	      for (const link of seg.links) {
227	        link.gen = gen;
228	        r.poolUsed += link.units;
229	        if (link.kind === 'own') {
230	          link.lender.pendingLends += link.units;
231	          link.lender.resvAsLender.add(entry);
232	        } else {
233	          r.poolResv.add(link);
234	          r.poolResvUnits += link.units;
235	          if (m === r) m.resvAsMember.add(entry);
236	        }
237	      }
238	    }
239	    entry.segs = segs;
240	    entry.holdsHeld = true;
241	  }
242	
243	  // Plan, check pool room, apply — or reject without touching anything. The
244	  // whole combo draws pool room: a member's own slice and every ancestor lend
245	  // are partitions OF the pool, not capacity beyond it. Feasibility is
246	  // therefore simply poolUsed + total combo units <= poolLimit; the plan's
247	  // own/lender/pool partition only decides which own window each unit lands
248	  // on (and thus where its flip reclaims it).
249	  function tryGather(entry, segs) {
250	    const r = entry.owner.root;
251	    let total = 0;
252	    for (const seg of segs) total += seg.units;
253	    if (r.poolUsed + total > r.poolLimit) {
254	      for (const seg of segs) {
255	        seg.own = 0;
256	        seg.links = [];
257	      }
258	      return false;
259	    }
260	    planGather(segs);
261	    applyGather(entry, segs);
262	    return true;
263	  }
264	
265	  // Release a held reservation wholesale. Pool room is refunded only while
266	  // the charged pool window is still the current one; a pool flip already
267	  // reclaimed it (the link is marked released and its gen is stale).
268	  function releaseHolds(entry) {
269	    if (!entry.holdsHeld || entry.segs === null) return;
270	    const r = entry.owner.root;
271	    for (const seg of entry.segs) {
272	      const m = seg.gate;
273	      if (!seg.ownReleased && seg.own > 0) {
274	        seg.ownReleased = true;
275	        m.pendingOwn -= seg.own;
276	        m.resvAsMember.delete(entry);
277	        if (seg.gen === r.poolGen) r.poolUsed -= seg.own;
278	      }
279	      for (const link of seg.links) {
280	        if (link.released) continue;
281	        link.released = true;
282	        if (link.kind === 'pool') {
283	          // delete() reports whether the link still charged the pool: a pool
284	          // flip already cleared the set and zeroed poolResvUnits, so a stale
285	          // link must not subtract twice.
286	          if (r.poolResv.delete(link)) r.poolResvUnits -= link.units;
287	          m.resvAsMember.delete(entry);
288	        } else {
289	          link.lender.pendingLends -= link.units;
290	          link.lender.resvAsLender.delete(entry);
291	        }
292	        if (link.gen === r.poolGen) r.poolUsed -= link.units;
293	      }
294	    }
295	    entry.holdsHeld = false;
296	    entry.segs = null;
297	  }
298	
299	  // --- Handles --------------------------------------------------------------
300	  //
301	  // The handle exposes exactly one own property, release, as a closure: the
302	  // destructured method called without a receiver works the same. Every link
303	  // remembers the generations of both sides, so a release after either window
304	  // flipped never subtracts quota that flip already settled.
305	
306	  function makeHandle(records) {
307	    let active = true;
308	    return {
309	      release() {
310	        if (!active) return;
311	        active = false;
312	        for (const rec of records) {
313	          const seg = rec.seg;
314	          const m = seg.member;
315	          const r = m.root;
316	          m.openHandles.delete(rec);
317	          if (seg.mgen === m.ownGen && seg.own > 0) {
318	            m.inFlight -= seg.own;
319	          }
320	          for (const link of seg.links) {
321	            const memberLive = seg.mgen === m.ownGen;
322	            const lenderLive =
323	              link.kind === 'pool' ? link.lgen === r.poolGen : link.lgen === link.lender.ownGen;
324	            if (!memberLive || !lenderLive) continue; // a window flip settled it
325	            m.inFlight -= link.units;
326	            m.borrowedInFlight -= link.units;
327	            if (link.kind === 'pool') {
328	              r.poolLinks.delete(link);
329	            } else {
330	              link.lender.lentLinks.delete(link);
331	              link.lender.inFlight -= link.units;
332	              link.lender.lentInFlight -= link.units;
333	            }
334	          }
335	        }
336	      },
337	    };
338	  }
339	
340	  // Commit a single-gate occupation with the baseline partition: own quota
341	  // first, every shortfall drawn straight from the root pool.
342	  function commitSingle(target, units) {
343	    const r = target.root;
344	    r.poolUsed += units;
345	    chargeDraw(target, units);
346	    let seg;
347	    if (target === r) {
348	      target.usedOwn += units;
349	      target.inFlight += units;
350	      seg = { member: target, units, own: units, mgen: target.ownGen, links: [] };
351	    } else {
352	      const ownPart = Math.min(units, Math.max(0, target.limit - target.usedOwn));
353	      const borrowPart = units - ownPart;
354	      target.usedOwn += ownPart;
355	      target.inFlight += units;
356	      target.borrowedInFlight += borrowPart;
357	      const links = [];
358	      if (borrowPart > 0) {
359	        const link = {
360	          kind: 'pool',
361	          lender: r,
362	          member: target,
363	          units: borrowPart,
364	          lgen: r.poolGen,
365	          mgen: target.ownGen,
366	        };
367	        r.poolLinks.add(link);
368	        links.push(link);
369	      }
370	      seg = { member: target, units, own: ownPart, mgen: target.ownGen, links };
371	    }
372	    const rec = { seg };
373	    target.openHandles.add(rec);
374	    return makeHandle([rec]);
375	  }
376	
377	  // Commit a fully gathered combo: provisional promises become admitted
378	  // occupations. Pool room was charged at gather time, so poolUsed does not
379	  // move here.
380	  function commitCombo(entry) {
381	    const r = entry.owner.root;
382	    const records = [];
383	    const lenderCleanup = new Set();
384	    for (const seg0 of entry.segs) {
385	      const m = seg0.gate;
386	      const units = seg0.units;
387	      chargeDraw(m, units);
388	      let seg;
389	      if (m === r) {
390	        // The root member's whole slice is its own window and drew the pool
391	        // directly; consume its pool reservation link so it does not survive
392	        // the commit as uncommitted quota.
393	        for (const l0 of seg0.links) {
394	          if (l0.kind === 'pool' && r.poolResv.delete(l0)) r.poolResvUnits -= l0.units;
395	        }
396	        m.usedOwn += units;
397	        m.inFlight += units;
398	        m.resvAsMember.delete(entry);
399	        seg = { member: m, units, own: units, mgen: m.ownGen, links: [] };
400	      } else {
401	        const ownPart = seg0.own;
402	        m.usedOwn += ownPart;
403	        m.pendingOwn -= ownPart;
404	        m.resvAsMember.delete(entry);
405	        m.inFlight += units;
406	        const links = [];
407	        for (const l0 of seg0.links) {
408	          const link = {
409	            kind: l0.kind,
410	            lender: l0.lender,
411	            member: m,
412	            units: l0.units,
413	            lgen: l0.kind === 'pool' ? r.poolGen : l0.lender.ownGen,
414	            mgen: m.ownGen,
415	          };
416	          if (l0.kind === 'pool') {
417	            if (r.poolResv.delete(l0)) r.poolResvUnits -= l0.units;
418	            r.poolLinks.add(link);
419	          } else {
420	            const g = l0.lender;
421	            g.usedOwn += l0.units;
422	            g.pendingLends -= l0.units;
423	            lenderCleanup.add(g);
424	            g.inFlight += l0.units;
425	            g.lentInFlight += l0.units;
426	            link.pgen = r.poolGen; // pool window this lend charged
427	            g.lentLinks.add(link);
428	          }
429	          links.push(link);
430	        }
431	        m.borrowedInFlight += units - ownPart;
432	        seg = { member: m, units, own: ownPart, mgen: m.ownGen, links };
433	      }
434	      const rec = { seg };
435	      m.openHandles.add(rec);
436	      records.push(rec);
437	    }
438	    // One entry may borrow from the same ancestor for several sibling
439	    // members; drop its lender registration once, after every link settled.
440	    for (const g of lenderCleanup) g.resvAsLender.delete(entry);
441	    entry.holdsHeld = false;
442	    entry.segs = null;
443	    return makeHandle(records);
444	  }
445	
446	  // --- Queue entry lifecycle ------------------------------------------------
447	
448	  function detachSignal(entry) {
449	    if (entry.signal !== null) {
450	      entry.signal.removeEventListener('abort', entry.onAbort);
451	      entry.signal = null;
452	    }
453	  }
454	
455	  // One queue entry leaves the queue exactly once, and exactly one of
456	  // granted / refused / expired / cancelled moves as a result.
457	  function settleEntry(entry, outcome) {
458	    if (entry.removed) return;
459	    const ownerRoot = entry.owner.root;
460	    entry.removed = true;
461	    ownerRoot.liveQueued -= 1;
462	    clearTimeout(entry.timer);
463	    detachSignal(entry);
464	    for (const charge of entry.waitCharges) charge.gate.waiting -= charge.units;
465	    if (outcome === 'granted') {
466	      const handle = entry.combo ? commitCombo(entry) : commitSingle(entry.owner, entry.units);
467	      entry.owner.granted += 1;
468	      entry.resolve(handle);
469	      return;
470	    }
471	    // Expiry, cancellation and refusal give back any hold; none of those
472	    // outcomes itself counts as a reservation rollback.
473	    if (entry.combo) releaseHolds(entry);
474	    if (outcome === 'refused') {
475	      entry.owner.refused += 1;
476	      entry.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
477	    } else if (outcome === 'cancelled') {
478	      entry.owner.cancelled += 1;
479	      entry.reject(
480	        new QuotaExceededError('CANCELLED', 'queued request was cancelled before quota was available'),
481	      );
482	    } else {
483	      entry.owner.expired += 1;
484	      entry.reject(
485	        new QuotaExceededError('WAIT_EXPIRED', 'queued request expired before quota was available'),
486	      );
487	    }
488	  }
489	
490	  // The wait timer measures real elapsed time, like the baseline. The
491	  // deadline field additionally gates window-flip sweeps when the monotonic
492	  // clock and the wall clock disagree (mocked/frozen clocks).
493	  function armEntry(entry, delay) {
494	    entry.timer = setTimeout(() => {
495	      if (entry.removed) return;
496	      settleEntry(entry, 'expired');
497	    }, Math.max(1, delay));
498	    if (typeof entry.timer.unref === 'function') entry.timer.unref();
499	  }
500	
501	  // At the same moment expiry beats cancellation: an abort arriving once the
502	  // deadline has already passed settles as WAIT_EXPIRED.
503	  function onEntryAbort(entry) {
504	    if (entry.removed) return;
505	    if (entry.deadline <= now()) {
506	      settleEntry(entry, 'expired');
507	    } else {
508	      settleEntry(entry, 'cancelled');
509	    }
510	  }
511	
512	  function recomputeMinDeadline() {
513	    const r = state.root;
514	    let min = Infinity;
515	    const q = r.queue;
516	    for (let i = r.head; i < q.length; i += 1) {
517	      const entry = q[i];
518	      if (!entry.removed && entry.deadline < min) min = entry.deadline;
519	    }
520	    r.minDeadline = min;
521	  }
522	
523	  // Expiry is judged before quota allocation: anything due at or before the
524	  // flip moment expires rather than being granted.
525	  function sweepExpired(t) {
526	    const r = state.root;
527	    if (r.minDeadline > t) return;
528	    let min = Infinity;
529	    for (let i = r.head; i < r.queue.length; i += 1) {
530	      const entry = r.queue[i];
531	      if (entry.removed) continue;
532	      if (entry.deadline <= t) settleEntry(entry, 'expired');
533	      else if (entry.deadline < min) min = entry.deadline;
534	    }
535	    r.minDeadline = min;
536	  }
537	
538	  // Allocation walks arrivals in order against the freshly reset pool. A head
539	  // combo that cannot be gathered whole does not starve later arrivals: a
540	  // later request that fits outright passes it and the combo yields once;
541	  // after yielding twice (cumulatively, across flips) it becomes a hard
542	  // barrier like a non-fitting single. The pass is O(1) per live queue entry:
543	  // a single monotonic counter (serveWave, bumped once per overtaking serve)
544	  // lets each blocked combo derive its yield count without being touched by
545	  // the requests that pass it.
546	  function allocate() {
547	    const r = state.root;
548	    const q = r.queue;
549	    let wave = r.serveWave; // overtakes counted so far, monotonic across passes
550	    let stopWave = Infinity; // earliest wave at which a blocker hardens
551	    let blockerCount = 0; // blocked combos registered earlier in this/prev passes
552	    for (let i = r.head; i < q.length; i += 1) {
553	      const entry = q[i];
554	      if (entry.removed) continue;
555	      if (wave >= stopWave) break;
556	      let served = false;
557	      if (!entry.combo) {
558	        if (r.poolUsed + entry.units > r.poolLimit) break;
559	        settleEntry(entry, 'granted');
560	        served = true;
561	      } else {
562	        // Combo's turn against the fresh pool: the pool flip reclaimed its
563	        // pool side; release the surviving own-side holds and gather anew.
564	        if (entry.holdsHeld) releaseHolds(entry);
565	        const segs = buildSegs(entry.comboGates, (g) => entry.comboUnits.get(g));
566	        if (tryGather(entry, segs)) {
567	          settleEntry(entry, 'granted');
568	          served = true;
569	        } else {
570	          // Any step short: the plan touched nothing; count one whole
571	          // rollback (no other counter moves) and register a soft barrier.
572	          entry.owner.rolledBack += 1;
573	          if (entry.blockG !== -1) entry.yields += wave - entry.blockG;
574	          entry.blockG = wave;
575	          const hardensAt = wave + (2 - entry.yields);
576	          blockerCount += 1;
577	          if (hardensAt < stopWave) stopWave = hardensAt;
578	        }
579	      }
